import type { TableName, TableSchemaDotWalk } from './Table';
/** @interface */
type DatabaseViewField<T extends TableName = TableName> = Now.Internal.WithID<{
    /** Column name from `table` to expose in the view. Supports schema-guided autocomplete. */
    field: TableSchemaDotWalk<T> | (string & {});
}>;
/** @interface */
type DatabaseViewTable<T extends TableName = TableName> = Now.Internal.WithID<{
    /**
     * The table to join into the view. In a scoped app, prefer a table in the same scope,
     * or a scoped table that extends an out-of-box table, when targeting platform data.
     */
    table: T;
    /**
     * Disambiguates this table's fields inside `whereClause` (e.g. `usr` for `sys_user`).
     * The platform rejects prefixes containing an underscore or exceeding 30 characters, and
     * must be unique across every table in the same view — a collision produces a broken or
     * ambiguous join and is not caught by the platform itself.
     */
    variablePrefix: string;
    /**
     * `false` (default) produces an INNER JOIN — only rows with matches in every joined table
     * appear. `true` produces a LEFT OUTER JOIN — all rows from prior tables appear, with empty
     * values for unmatched columns from this table. Needed for "find records with no related X"
     * style reporting.
     * @default false
     */
    leftJoin?: boolean;
    /**
     * Join order relative to other tables in this view. Affects query performance on large
     * tables — put the most selective/smallest table first.
     * @default 100
     */
    order?: number;
    /**
     * A raw join/filter predicate using `variablePrefix`-qualified field names, e.g.
     * `usr_sys_id=role_user`. This is not an encoded query string.
     */
    whereClause?: string;
    /** Whether this joined table is active. @default true */
    active?: boolean;
    /**
     * Column names from `table` to expose in the view. Many real views join a table purely for
     * filtering (via `whereClause`) without exposing any of its columns — omit or leave empty
     * in that case.
     *
     * Each entry is an object with a required `$id` and `field` name. The `$id` is the unique
     * identifier for the `sys_db_view_table_field` record, matching the platform's `sys_id`.
     * Provide a unique `$id` for every field; use distinct `$id`s when the same field must appear
     * more than once under the same view table.
     */
    fields?: Array<DatabaseViewField<T>>;
}>;
/**
 * Narrows each entry in `tables` so its `fields` are checked against the specific `table`
 * declared on that same entry, instead of the union of every table in the system. Inferring
 * `Tables` as a tuple (via a `const` type parameter on `DatabaseView`) lets each array position
 * carry its own table literal.
 */
type DatabaseViewTables<Tables extends readonly DatabaseViewTable[]> = {
    [K in keyof Tables]: Tables[K] extends {
        table: infer T extends TableName;
    } ? DatabaseViewTable<T> : Tables[K];
};
/** @interface */
type DatabaseViewConfig<Tables extends readonly DatabaseViewTable[] = DatabaseViewTable[]> = Now.Internal.WithMetadata<{
    /**
     * Name of the database view. This is the record's identity key: the platform enforces
     * uniqueness of the normalized name across all database views, so `DatabaseView`
     * intentionally omits a top-level `$id`. The platform silently normalizes this value
     * (lowercase, non-alphanumeric characters replaced with `_`) before storing it, and this
     * is also the key used to identify the record across rebuilds — supply an already-normalized
     * name to avoid a duplicate view being created on the next build.
     */
    name: string;
    /** Display label shown for this view in admin views and reporting UIs. Defaults to empty. */
    label?: string;
    /** Plural form of the label, used where the platform needs a plural noun (e.g. list titles). Defaults to empty. */
    plural?: string;
    /** Free-text description of the view's purpose. Defaults to empty. */
    description?: string;
    /**
     * The tables joined into this view, in join order. May be empty — ServiceNow allows
     * database views with no joined tables.
     */
    tables: DatabaseViewTables<Tables>;
}>;
export declare function DatabaseView<const Tables extends readonly DatabaseViewTable[]>(config: DatabaseViewConfig<Tables>): DatabaseViewConfig<Tables>;
export {};
